    #[test]
    fn file_contents_dense_lifecycle() {
        let mut contents = FileContents::dense(b"hello world".to_vec());
        assert_eq!(contents.len().unwrap(), 11);

        let mut buf = [0u8; 5];
        assert_eq!(contents.read_at(0, &mut buf).unwrap(), 5);
        assert_eq!(&buf, b"hello");

        assert_eq!(contents.read_at(6, &mut buf).unwrap(), 5);
        assert_eq!(&buf, b"world");

        // Read past end
        assert_eq!(contents.read_at(20, &mut buf).unwrap(), 0);

        // Write
        assert_eq!(contents.write_at(6, b"there").unwrap(), 5);
        let mut full_buf = [0u8; 11];
        assert_eq!(contents.read_at(0, &mut full_buf).unwrap(), 11);
        assert_eq!(&full_buf, b"hello there");

        // Resize shrink
        contents.resize(5).unwrap();
        assert_eq!(contents.len().unwrap(), 5);
        assert_eq!(contents.read_at(0, &mut buf).unwrap(), 5);
        assert_eq!(&buf, b"hello");

        // Resize grow
        contents.resize(8).unwrap();
        assert_eq!(contents.len().unwrap(), 8);
        let mut grow_buf = [0u8; 8];
        assert_eq!(contents.read_at(0, &mut grow_buf).unwrap(), 8);
        assert_eq!(&grow_buf, b"hello\0\0\0");
    }

    #[test]
    fn file_contents_rootfs_backed_lifecycle() {
        let mut contents = FileContents::shared_backed(
            std::sync::Arc::from(&b"initial base data"[..]),
            std::collections::BTreeMap::new(),
            17,
        );
        assert_eq!(contents.len().unwrap(), 17);

        let mut buf = [0u8; 7];
        assert_eq!(contents.read_at(0, &mut buf).unwrap(), 7);
        assert_eq!(&buf, b"initial");

        // Write overlay
        assert_eq!(contents.write_at(8, b"dirty").unwrap(), 5);
        let mut full = [0u8; 17];
        assert_eq!(contents.read_at(0, &mut full).unwrap(), 17);
        assert_eq!(&full, b"initial dirtydata");

        // Resize shrink
        contents.resize(10).unwrap();
        assert_eq!(contents.len().unwrap(), 10);
        let mut ten = [0u8; 10];
        assert_eq!(contents.read_at(0, &mut ten).unwrap(), 10);
        assert_eq!(&ten, b"initial di");

        // Resize grow within base
        contents.resize(14).unwrap();
        assert_eq!(contents.len().unwrap(), 14);
        let mut fourteen = [0u8; 14];
        assert_eq!(contents.read_at(0, &mut fourteen).unwrap(), 14);
        assert_eq!(&fourteen, b"initial dise d");

        // Resize grow past base
        contents.resize(20).unwrap();
        assert_eq!(contents.len().unwrap(), 20);
        let mut twenty = [0u8; 20];
        assert_eq!(contents.read_at(0, &mut twenty).unwrap(), 20);
        assert_eq!(&twenty, b"initial dise data\0\0\0");
    }

    #[test]
    fn file_contents_host_backed_lifecycle() {
        let tmp = tempfile::NamedTempFile::new().unwrap();
        std::fs::write(tmp.path(), b"host storage data").unwrap();
        let rw_fd = unsafe {
            libc::open(
                std::ffi::CString::new(tmp.path().to_str().unwrap())
                    .unwrap()
                    .as_ptr(),
                libc::O_RDWR,
            )
        };
        assert!(rw_fd >= 0);
        let owned = unsafe { std::os::fd::OwnedFd::from_raw_fd(rw_fd) };
        let mut contents = FileContents::host_backed(owned);

        assert_eq!(contents.len().unwrap(), 17);

        let mut buf = [0u8; 4];
        assert_eq!(contents.read_at(0, &mut buf).unwrap(), 4);
        assert_eq!(&buf, b"host");

        assert_eq!(contents.write_at(5, b"buffer").unwrap(), 6);
        let mut full = [0u8; 17];
        assert_eq!(contents.read_at(0, &mut full).unwrap(), 17);
        assert_eq!(&full, b"host buffere data");

        contents.resize(4).unwrap();
        assert_eq!(contents.len().unwrap(), 4);
        assert_eq!(contents.read_at(0, &mut buf).unwrap(), 4);
        assert_eq!(&buf, b"host");
    }
}

crates/carrick-kernel/src/dispatch/fs/st:
//! fd stat/statx record assembly split out of dispatch/fs.rs (WS-F3):
//! the synthetic stdio (label, st_mode) probe and the fstat/statx
//! buffer writers + StatRecord builder. Pure `impl SyscallDispatcher` move.
use super::*;
use crate::linux_abi::LinuxErrno;

impl<'a> FsView<'a> {
    /// The synthetic `(label, st_mode)` for a bare stdio fd (0/1/2) with no
    /// OpenDescription. Glibc fstat()s stdio on startup to pick its tty/file/
    /// pipe code path, so report the REAL host type (a pty → S_IFCHR, a pipe →
    /// S_IFIFO, a redirect → S_IFREG; the S_IF* values match Linux). When the
    /// fd is the `carrick run -t` controlling tty, label it `/dev/pts/N` so the
    /// synthetic st_ino matches `stat("/dev/pts/N")` — the equality `ttyname(3)`
    /// checks between `fstat(fd)` and the `/proc/self/fd/N` readlink target.
    /// Shared by `write_fd_stat` (fstat) and `write_fd_statx` (statx).
    pub(super) fn stdio_synthetic_label_mode(&self, fd: i32) -> (String, u32) {
        let label = if crate::host_tty::host_isatty(fd)
            && let Some(n) = self.pty_table().lock().controlling()
        {
            format!("/dev/pts/{n}")
        } else {
            match fd {
                0 => "/dev/stdin",
                1 => "/dev/stdout",
                _ => "/dev/stderr",
            }
            .to_string()
        };
        let mut host_st: libc::stat = unsafe { std::mem::zeroed() };
        // SAFETY: fd is a stdio fd; &host_st is a valid stat out-param.
        let mode = if unsafe { libc::fstat(fd, &mut host_st) } == 0 {
            (host_st.st_mode as u32 & LINUX_S_IFMT) | 0o620
        } else {
            LINUX_S_IFCHR | 0o620
        };
        (label, mode)
    }

    pub(super) fn write_fd_stat(
        &self,
        fd: i32,
        statbuf: u64,
        memory: &mut impl CurrentMmMemory,
    ) -> DispatchOutcome {
        match self.fd_stat_record(fd) {
            Ok(record) => write_stat_record(memory, statbuf, &record),
            Err(errno) => DispatchOutcome::errno(errno),
        }
    }

    pub(super) fn write_fd_statx(
        &self,
        fd: i32,
        statxbuf: u64,
        memory: &mut impl CurrentMmMemory,
    ) -> DispatchOutcome {
        match self.fd_stat_record(fd) {
            Ok(record) => write_statx_record(memory, statxbuf, &record),
            Err(errno) => DispatchOutcome::errno(errno),
        }
    }

    pub(super) fn fd_stat_record(&self, fd: i32) -> Result<StatRecord, LinuxErrno> {
        let Some(open_file) = self.open_file(fd) else {
            // A stdio fd the guest explicitly closed (and did not reopen) is
            // genuinely closed: report EBADF, not our still-open host stream.
            if is_stdio_fd(fd) && !self.stdio_is_closed(fd) {
                let (label, mode) = self.stdio_synthetic_label_mode(fd);
                return Ok(StatRecord::synthetic(&label, 0, mode)
                    .with_fs_identity(carrick_vfs::FsIdentity::Pipe));
            }
            return Err(LINUX_EBADF);
        };
        if open_file
            .description
            .concrete_backing::<crate::dispatch::ioring::IoUringBacking>()
            .is_some()
        {
            return Ok(StatRecord::synthetic("anon_inode:[io_uring]", 0, 0o600)
                .with_fs_identity(carrick_vfs::FsIdentity::AnonInode));
        }
        let Some(open) = open_file.description.read() else {
            return Err(LINUX_EBADF);
        };
        // A named FIFO opened by path is modelled as a `HostPipe` (no pty),
        // whose `stat_source` hands back a SYNTHETIC record (hashed inode,
        // mode 0o600). But a path-stat (lstat) of the same FIFO reports the
        // REAL on-disk inode/mode, so `os.path.samestat(lstat(fifo),
        // fstat(open(fifo)))` was False — shutil.rmtree's safe-fd walk then
        // mis-classified the pipe as a symlink ("Cannot call rmtree on a
        // symbolic link") instead of raising NotADirectoryError
        // (test_rmtree_on_named_pipe). Anonymous pipe2() ends are also
        // `HostPipe` but carry no recorded path, so they keep the synthetic
        // record. Recover the real FIFO stat from the fd's recorded path.
        let is_named_pipe = matches!(&*open, OpenDescription::HostPipe { pty: None, .. });
        let fs_id = open.fs_identity();
        let source = open.stat_source();
        drop(open);
        if is_named_pipe
            && let Some(path) = self.lookup_recorded_fd_open_path(fd)
            && let Some(real) = self.fs.rootfs_vfs.overlay.real_stat(&path, false)
            && real.kind == RootFsEntryKind::Fifo
        {
            return Ok(StatRecord::from_real(&real).with_fs_identity(fs_id));
        }
        let record = match source {
            OpenStatSource::Error(errno) => return Err(errno),
            OpenStatSource::Record(record) => record,
            OpenStatSource::HostStream {
                host_fd,
                identity,
                fallback_mode,
            } => {
                // fstat the real host fd to recover the Linux file type: a host
                // character device (/dev/null, /dev/zero, …) reports S_IFCHR
                // (mode 0o666, like Linux), a host pipe end reports S_IFIFO
                // (mode 0o600). The S_IF* type bits match between macOS and
                // Linux. Falls back to `fallback_mode` if the host fstat fails.
                let mut host_st: libc::stat = unsafe { std::mem::zeroed() };
                // SAFETY: host_fd is a live host fd; &host_st is a valid out-param.
                let mode = if unsafe { libc::fstat(host_fd.get(), &mut host_st) } == 0 {
                    let type_bits = host_st.st_mode as u32 & LINUX_S_IFMT;
                    let perms = if type_bits == LINUX_S_IFCHR {
                        0o666
                    } else {
                        0o600
                    };
                    type_bits | perms
                } else {
                    fallback_mode
                };
                // Preserve open-description identity in guest stat records.
                // A constant label made every HostPipe-backed object share one
                // synthetic inode: after `2>&1 >/dev/null`, GNU m4 therefore
                // mistook stderr's pipe for stdout's /dev/null and discarded
                // `dumpdef`, leaving autom4te with an empty builtin table.
                // Include the Linux file type because host inode numbers can
                // collide across devices; use `pipe_id` for identity because
                // BSD gives the two ends of one pipe different host inodes.
                let label = host_stream_stat_label(identity, mode & LINUX_S_IFMT);
                StatRecord::synthetic(&label, 0, mode)
            }
            // An open Directory or in-memory File: its fd-stat must report the
            // SAME st_ino/st_dev as a path-stat of the same path. Under
            // `--fs host` the path-stat (newfstatat/statx) uses the REAL host
            // inode via `overlay.real_stat`; mirror it here so
            // `os.path.samestat(lstat(dir), fstat(open(dir)))` is True (the
            // synthetic `fallback` hashes the path to a DIFFERENT inode). When
            // no host stat exists (MemoryBackend), the path-stat is ALSO the
            // synthetic record, so the `fallback` already matches.
            OpenStatSource::PathRecord { path, fallback } => {
                if let Some(real) = self.fs.rootfs_vfs.overlay.real_stat(&path, true) {
                    StatRecord::from_real(&real)
                } else if let Some(real) = self
                    .fs
                    .vfs_mounts
                    .resolve(&path)
                    .and_then(|m| m.vfs.real_stat(&m.full_path, true))
                {
                    // The path-stat (newfstatat) falls through to the VFS mount
                    // table when the overlay misses — a bind mount (`-v`), /proc,
                    // /dev. Mirror it so a bind-mounted DIRECTORY's fstat reports
                    // the SAME (real host) inode as its path-stat; otherwise
                    // SameFile(fstat(open(dir)), stat(dir)) is false (Go os
                    // TestFileChdir; Python os.path.samestat). Without this the
                    // fd fell back to the path-HASH inode while the path-stat
                    // returned the real host inode.
                    StatRecord::from_real(&real)
                } else if let Some(real) = self
                    .fs
                    .rootfs_vfs
                    .immutable_lower_real_stat(&path, true)
                    .map(|real| StatRecord::from_real(&real))
                    .filter(|real| real.mode & LINUX_S_IFMT == fallback.mode & LINUX_S_IFMT)
                {
                    // A DIRECTORY only the immutable cache lower holds. Its
                    // path-stat now reports the lower's real host inode (see
                    // `layered_identity_record`), so this lane must too —
                    // otherwise fixing the regular-file case would simply move
                    // the `samestat` disagreement onto directories. Regular
                    // files never reach here: they open as a real `HostFile`.
                    real
                } else {
                    fallback
                }
            }
            OpenStatSource::HostFile { host_fd, fallback } => {
                let mut host_st: libc::stat = unsafe { std::mem::zeroed() };
                // SAFETY: host_fd is a live host fd; &host_st is a valid out-param.
                if unsafe { libc::fstat(host_fd.get(), &mut host_st) } == 0 {
                    let inode_rec = self
                        .fs
                        .rootfs_vfs
                        .get_or_fill_host_inode(host_fd.get(), &host_st);
                    let device = if inode_rec.dev_type != 0 {
                        Some((inode_rec.dev_type, inode_rec.rdev))
                    } else {
                        None
                    };
                    let mut real = super::real_stat_from_libc(&host_st);
                    real.mode = inode_rec.mode & 0o7777;
                    real.uid = inode_rec.uid;
                    real.gid = inode_rec.gid;
                    let mut record = StatRecord::from_real(&real);
                    record.apply_device_node(device);
                    return Ok(record.with_fs_identity(fs_id));
                }
                fallback
            }
        };
        Ok(record.with_fs_identity(fs_id))
    }

    /// Build a [`StatRecord`] from a real backing stat, applying the `mknod(2)`
    /// device-node override (S_IFCHR/S_IFBLK type + st_rdev) when `path` is a
    /// device marker. The marker's FULL guest mode (including the device type
    /// bits) is carried VERBATIM in `RealStat.mode` (the host backend stores it
    /// raw in `CARRICK_MODE_XATTR`); `from_real`/`linux_mode` masks those type
    /// bits off, so we recover the device type from `real.mode` here WITHOUT a
    /// second xattr read — the common stat hot path pays nothing. Only when the
    /// type bits actually name a device do we fetch the (rare) `st_rdev` xattr.
    /// A plain regular file (no device type bits) is returned unchanged.
    pub(super) fn stat_record_with_device(
        &self,
        path: &str,
        real: &carrick_vfs::fs_backend::RealStat,
    ) -> StatRecord {
        let mut record = StatRecord::from_real(real);
        let type_bits = real.mode & LINUX_S_IFMT;
        if type_bits == LINUX_S_IFCHR || type_bits == LINUX_S_IFBLK {
            let rdev = self
                .fs
                .rootfs_vfs
                .overlay
                .device_node(path)
                .map(|(_, dev)| dev)
                .unwrap_or(0);
            record.apply_device_node(Some((type_bits, rdev)));
        }
        record
    }

    /// Give a layered-lookup result the identity of the host inode that
    /// actually backs it.
    ///
    /// The layered resolver owns EXISTENCE and kind — whiteouts, copy-up,
    /// cross-layer symlinks. It cannot own identity: `vfs::Metadata` and
    /// `RootFsMetadata` carry no inode, no link count and no timestamps, so
    /// `StatRecord::from_metadata` hashes the path instead. That is fine for a
    /// synthetic entry, but an entry only the immutable cache lower holds is a
    /// REAL host file — `open()` hands back its host fd, `fstat` reports its
    /// APFS inode and `getdents64` already publishes that inode as `d_ino`.
    /// A path hash here made `stat(p).st_ino != fstat(open(p)).st_ino`, which
    /// GNU coreutils `cp` reads as the source being replaced mid-copy
    /// (`cp: skipping file '…', as it was replaced while being copied` →
    /// LTP `execve02` TBROK once the cached lower was enabled for HvPatch).
    ///
    /// Kind agreement gates the adoption: a mismatch means the resolver landed
    /// on something other than the lower entry of that name, so its answer
    /// stands.
    pub(super) fn layered_identity_record(
        &self,
        path: &str,
        follow: bool,
        metadata: &RootFsMetadata,
    ) -> StatRecord {
        match self.fs.rootfs_vfs.immutable_lower_real_stat(path, follow) {
            Some(real) if real.kind == metadata.kind => StatRecord::from_real(&real),
            _ => StatRecord::from_metadata(metadata),
        }
    }

    /// `statx` twin of [`stat_record_with_device`](Self::stat_record_with_device):
    pub(super) fn path_stat_record(
        &self,
        context: &crate::kernel::KernelContext,
        dirfd: u64,
        path: &str,
        flags: u64,
    ) -> Result<StatRecord, LinuxErrno> {
        let at_flags = carrick_abi::LinuxAtFlags::from_bits_retain(flags);
        let lookup = self.lookup_path(dirfd, path, at_flags, LookupIntent::Stat { context })?;
        let _ = &lookup.resolved_path;
        let _ = lookup.fast_path();
        let _ = lookup.resolved_path();
        lookup.into_stat()
    }

    fn statfs(
        &self,
        pathname: GuestPtr,
        buffer: GuestPtr,
        memory: &mut impl CurrentMmMemory,
    ) -> Result<DispatchOutcome, DispatchError> {
        let path = read_guest_c_string(memory, pathname.0)?;
        // An empty pathname is ENOENT (statfs has no AT_EMPTY_PATH form). glibc
        // pathconf(path, _PC_LINK_MAX) validates the path via statfs, so
        // statfs("") must fail rather than succeed and yield LINK_MAX
        // (pathconf02 empty-string case).
        if path.is_empty() {
            return Ok(DispatchOutcome::errno(LINUX_ENOENT));
        }
        let path = self.resolve_at_path(LINUX_AT_FDCWD, &path)?;
        // statfs(2) follows symlinks; a symlink CYCLE is ELOOP. resolve_at_path
        // doesn't cap symlink depth, so canonicalize here to surface a cycle as
        // ELOOP (LTP statfs02/statvfs02). Other resolution errors fall through to
        // layered_metadata, which reports ENOENT/ENOTDIR/ENAMETOOLONG as before.
        let path = match self.canonicalize_following(&path) {
            Ok(resolved) => resolved,
            Err(e) if e == crate::linux_abi::LINUX_ELOOP => return Ok(DispatchOutcome::errno(e)),
            Err(_) => path,
        };
        // Consult the layered view (overlay/disk first, then rootfs) so
        // that files the guest created in the overlay are visible here
        // too — a rootfs-direct lookup would miss them.
        if let Err(errno) = self.layered_metadata(&path) {
            return Ok(DispatchOutcome::errno(errno));
        }
        let statfs = if let Some(m) = self.fs.vfs_mounts.resolve(&path) {
            m.vfs.fs_identity().statfs()
        } else {
            self.fs.rootfs_vfs.statfs()
        };
        Ok(write_statfs(memory, buffer.0, &statfs))
    }

    fn fstatfs(&self, fd: Fd, buf: GuestPtr, memory: &mut impl CurrentMmMemory) -> DispatchOutcome {
        let record = match self.fd_stat_record(fd.0) {
            Ok(record) => record,
            Err(errno) => return DispatchOutcome::errno(errno),
        };
        let statfs = if record.fs_identity == carrick_vfs::FsIdentity::Overlay {
            self.fs.rootfs_vfs.statfs()
        } else {
            record.fs_identity.statfs()
        };
        write_statfs(memory, buf.0, &statfs)
    }

    /// Single-component `newfstatat`/`statx` through a TRUSTED host dirfd:
    /// one `fstatat(host_dirfd, name, AT_SYMLINK_NOFOLLOW)` plus (on a
    /// regular-file/dir hit) one no-atime leaf open for the carrick xattr
    /// metadata — replacing the anchor re-verify + parent validation + the
    /// layered stat stack. A non-symlink hit makes follow and no-follow
    /// coincide, so the caller's AT_SYMLINK_NOFOLLOW needs no case split; a
    /// symlink child falls back (exact lstat semantics INCLUDING the
    /// link-owner xattrs stay on the slow path). Missing is authoritative
    /// (`Some(Err(ENOENT))`); `None` ⇒ take the full path.
    pub(super) fn try_trusted_dirfd_stat(
        &self,
        dirfd: u64,
        path: &str,
    ) -> Option<Result<StatRecord, LinuxErrno>> {
        use std::os::fd::{FromRawFd, OwnedFd};
        // fts walkers (GNU find, and every fts-based tool) stat each
        // directory they descend as "." relative to the directory's OWN fd.
        // The trusted dir IS the object: serve fstat(host_dirfd) directly —
        // no component gate, no leaf probe (the metadata pass reads the
        // already-open fd when metadata xattrs may exist anywhere).
        if path == "." {
            let (dir_path, host_dir) = self.trusted_dir_of(dirfd)?;
            if !host_dir
                .namespace_is_current_against(self.fs.rootfs_vfs.overlay.structural_generation())
            {
                return None;
            }
            if !host_dir.is_merged_upper() {
                // A lower dirfd's own identity is now the cache directory's
                // real host inode either way (`layered_identity_record`), so
                // this is no longer about which inode to report — it is that
                // the anchor may have been whiteout-shadowed or copied up
                // since it was opened, which only the layered walk can see.
                return None;
            }
            if !self.cred_snapshot().euid.is_root() {
                return None;
            }
            let mut st: libc::stat = unsafe { std::mem::zeroed() };
            if unsafe { libc::fstat(host_dir.fd.raw(), &mut st) } != 0 {
                return None;
            }
            if st.st_mode as u32 & libc::S_IFMT as u32 != libc::S_IFDIR as u32 {
                return None;
            }
            let (override_mode, uid, gid, _) = if self.fs.rootfs_vfs.overlay.serves_plain_metadata()
            {
                (None, None, None, false)
            } else {
                carrick_vfs::fs_backend::fd_carrick_meta(host_dir.fd.raw())
            };
            let on_disk_mode = st.st_mode as u32 & 0o7777;
            let real = carrick_vfs::fs_backend::RealStat {
                kind: RootFsEntryKind::Directory,
                ino: st.st_ino,
                nlink: st.st_nlink as u32,
                mode: override_mode
                    .map(|m| m & 0o7777)
                    .unwrap_or(if on_disk_mode == 0 {
                        0o755
                    } else {
                        on_disk_mode
                    }),
                uid: uid.unwrap_or(carrick_abi::NsUid::ROOT),
                gid: gid.unwrap_or(carrick_abi::NsGid::ROOT),
                size: st.st_size as u64,
                blocks: Some(st.st_blocks.max(0) as u64),
                atime: (st.st_atime, carrick_portable::stat_atime_nsec(&st)),
                mtime: (st.st_mtime, carrick_portable::stat_mtime_nsec(&st)),
                ctime: (st.st_ctime, carrick_portable::stat_ctime_nsec(&st)),
            };
            return Some(Ok(self.stat_record_with_device(&dir_path, &real)));
        }
        let name = Self::trusted_lane_component(path)?;
        let (dir_path, host_dir) = self.trusted_dir_of(dirfd)?;
        if !host_dir
            .namespace_is_current_against(self.fs.rootfs_vfs.overlay.structural_generation())
        {
            return None;
        }
        if !host_dir.is_merged_upper() {
            return None;
        }
        let full = self.trusted_child_path(&dir_path, name)?;
        // A non-root fsuid needs the ancestor search-permission checks. fsuid,
        // not euid: it is the identity every DAC check uses (setfsuid(2)), and
        // a bypass keyed on the other one is how a permission check gets
        // skipped for a caller that has genuinely dropped privilege.
        if !self.dac_overrides_permissions() {
            return None;
        }
        let name_c = std::ffi::CString::new(name).ok()?;
        let mut st: libc::stat = unsafe { std::mem::zeroed() };
        if unsafe {
            libc::fstatat(
                host_dir.fd.raw(),
                name_c.as_ptr(),
                &mut st,
                libc::AT_SYMLINK_NOFOLLOW,
            )
        } != 0
        {
            return if std::io::Error::last_os_error().raw_os_error() == Some(libc::ENOENT) {
                Some(Err(LINUX_ENOENT))
            } else {
                None
            };
        }
        let typ = st.st_mode as u32 & libc::S_IFMT as u32;
        let is_dir = typ == libc::S_IFDIR as u32;
        if !is_dir && typ != libc::S_IFREG as u32 {
            // Symlink (follow-vs-lstat + link-owner xattrs), FIFO (must never
            // be opened), real device: exact slow path.
            return None;
        }
        // Carrick metadata (mode/owner/socket) via one flistxattr-gated pass
        // on a no-atime fd — the same fill pattern (and the same benign
        // fstatat→openat window) as the stat cache's
        // `stat_cache_get_or_fill`. Skipped entirely when the root markers
        // prove NO entry anywhere carries metadata xattrs or marker nodes:
        // the fstatat above is then the complete guest answer, and the whole
        // stat costs ONE host syscall.
        let (override_mode, uid, gid, is_socket) =
            if self.fs.rootfs_vfs.overlay.serves_plain_metadata() {
                (None, None, None, false)
            } else {
                #[cfg(target_os = "macos")]
                const O_EVTONLY: libc::c_int = 0x8000;
                #[cfg(not(target_os = "macos"))]
                const O_EVTONLY: libc::c_int = libc::O_RDONLY;
                let leaf_flags = O_EVTONLY | libc::O_NOFOLLOW | libc::O_NONBLOCK | libc::O_CLOEXEC;
                let raw =
                    unsafe { libc::openat(host_dir.fd.raw(), name_c.as_ptr(), leaf_flags, 0) };
                if raw < 0 {
                    return None;
                }
                // SAFETY: freshly-opened owned fd, closed on drop.
                let leaf = unsafe { OwnedFd::from_raw_fd(raw) };
                let meta = carrick_vfs::fs_backend::fd_carrick_meta(raw);
                drop(leaf);
                meta
            };
        let kind = if is_dir {
            RootFsEntryKind::Directory
        } else if is_socket {
            RootFsEntryKind::Socket
        } else {
            RootFsEntryKind::File
        };
        let on_disk_mode = st.st_mode as u32 & 0o7777;
        let default_mode = if is_dir { 0o755 } else { 0o644 };
        let real = carrick_vfs::fs_backend::RealStat {
            kind,
            ino: st.st_ino,
            nlink: st.st_nlink as u32,
            // The override is carried VERBATIM (device markers keep their
            // type bits) — `stat_record_with_device` below recovers them,
            // exactly like the stat-cache hit path.
            mode: override_mode.unwrap_or(if on_disk_mode == 0 {
                default_mode
            } else {
                on_disk_mode
            }),
            uid: uid.unwrap_or(carrick_abi::NsUid::ROOT),
            gid: gid.unwrap_or(carrick_abi::NsGid::ROOT),
            size: st.st_size as u64,
            blocks: Some(st.st_blocks.max(0) as u64),
            atime: (st.st_atime, carrick_portable::stat_atime_nsec(&st)),
            mtime: (st.st_mtime, carrick_portable::stat_mtime_nsec(&st)),
            ctime: (st.st_ctime, carrick_portable::stat_ctime_nsec(&st)),
        };
        Some(Ok(self.stat_record_with_device(&full, &real)))
    }

    define_syscall! {
        fn sys_statfs(this, cx, path: GuestPtr, buf: GuestPtr) {

            this.statfs(path, buf, cx.memory)

        }

        fn sys_fstatfs(this, cx, fd: Fd, buf: GuestPtr) {

            Ok(this.fstatfs(fd, buf, cx.memory))

        }


        fn newfstatat(this, cx, dirfd: u64, pathname: GuestPtr, statbuf: GuestPtr, flags: u64) {
            let Some(at_flags) = carrick_abi::LinuxAtFlags::from_bits(flags) else {
                return Ok(DispatchOutcome::errno(LINUX_EINVAL));
            };
            // Only AT_SYMLINK_NOFOLLOW, AT_NO_AUTOMOUNT and AT_EMPTY_PATH are
            // valid; any other bit is EINVAL (fstatat01 case 4 passes flags=9999).
            if at_flags.bits() & !(LINUX_AT_SYMLINK_NOFOLLOW | LINUX_AT_NO_AUTOMOUNT | LINUX_AT_EMPTY_PATH) != 0 {
                return Ok(DispatchOutcome::errno(LINUX_EINVAL));
            }
            let pathname = pathname.0;
            let statbuf = statbuf.0;
            let memory = &mut *cx.memory;
            let path = read_guest_c_string(memory, pathname)?;
            match this.path_stat_record(cx.kernel, dirfd, &path, flags) {
                Ok(record) => Ok(write_stat_record(memory, statbuf, &record)),
                Err(errno) => Ok(DispatchOutcome::errno(errno)),
            }

        }

        fn x86_stat(this, cx, pathname: GuestPtr, statbuf: GuestPtr) {

            let pathname = pathname.0;
            let statbuf = statbuf.0;
            let memory = &mut *cx.memory;
            let path = read_guest_c_string(memory, pathname)?;
            match this.path_stat_record(cx.kernel, LINUX_AT_FDCWD, &path, 0) {
                Ok(record) => Ok(write_x8664_stat_record(memory, statbuf, &record)),
                Err(errno) => Ok(DispatchOutcome::errno(errno)),
            }

        }

        fn x86_fstat(this, cx, fd: Fd, statbuf: GuestPtr) {

            let statbuf = statbuf.0;
            let memory = &mut *cx.memory;
            match this.fd_stat_record(fd.0) {
                Ok(record) => Ok(write_x8664_stat_record(memory, statbuf, &record)),
                Err(errno) => Ok(DispatchOutcome::errno(errno)),
            }

        }

        fn x86_lstat(this, cx, pathname: GuestPtr, statbuf: GuestPtr) {

            let pathname = pathname.0;
            let statbuf = statbuf.0;
            let memory = &mut *cx.memory;
            let path = read_guest_c_string(memory, pathname)?;
            match this.path_stat_record(
                cx.kernel,
                LINUX_AT_FDCWD,
                &path,
                LINUX_AT_SYMLINK_NOFOLLOW,
            ) {
                Ok(record) => Ok(write_x8664_stat_record(memory, statbuf, &record)),
                Err(errno) => Ok(DispatchOutcome::errno(errno)),
            }

        }

        fn x86_newfstatat(this, cx, dirfd: u64, pathname: GuestPtr, statbuf: GuestPtr, flags: u64) {

            let Some(at_flags) = carrick_abi::LinuxAtFlags::from_bits(flags) else {
                return Ok(DispatchOutcome::errno(LINUX_EINVAL));
            };
            // Only AT_SYMLINK_NOFOLLOW, AT_NO_AUTOMOUNT and AT_EMPTY_PATH are
            // valid; any other bit is EINVAL (fstatat01 case 4 passes flags=9999).
            if at_flags.bits() & !(LINUX_AT_SYMLINK_NOFOLLOW | LINUX_AT_NO_AUTOMOUNT | LINUX_AT_EMPTY_PATH) != 0 {
                return Ok(DispatchOutcome::errno(LINUX_EINVAL));
            }
            let pathname = pathname.0;
            let statbuf = statbuf.0;
            let memory = &mut *cx.memory;
            let path = read_guest_c_string(memory, pathname)?;
            match this.path_stat_record(cx.kernel, dirfd, &path, flags) {
                Ok(record) => Ok(write_x8664_stat_record(memory, statbuf, &record)),
                Err(errno) => Ok(DispatchOutcome::errno(errno)),
            }

        }

        fn statx(this, cx, dirfd: u64, pathname: GuestPtr, flags: u64, mask: u64, statxbuf: GuestPtr) {

            let pathname = pathname.0;
            let statxbuf = statxbuf.0;
            let memory = &mut *cx.memory;

            if false {
                let uninit_real = std::mem::MaybeUninit::<carrick_vfs::fs_backend::RealStat>::uninit();
                let uninit_md = std::mem::MaybeUninit::<RootFsMetadata>::uninit();
                unsafe {
                    let _ = write_statx_real(memory, 0, &*uninit_real.as_ptr());
                    let _ = write_statx(memory, 0, &*uninit_md.as_ptr());
                }
                let _ = write_synthetic_statx(memory, 0, "", 0);
                let _ = write_synthetic_statx_mode(memory, 0, "", 0, 0);
            }

            if !linux_statx_flags_are_supported(flags) || mask & LINUX_STATX_RESERVED != 0 {
                return Ok(DispatchOutcome::errno(LINUX_EINVAL));
            }

            let path = read_guest_c_string(memory, pathname)?;
            if path.is_empty() {
                if flags & LINUX_AT_EMPTY_PATH == 0 {
                    return Ok(DispatchOutcome::errno(LINUX_ENOENT));
                }
                return Ok(this.write_fd_statx(dirfd as i32, statxbuf, memory));
            }

            let at_flags = carrick_abi::LinuxAtFlags::from_bits_retain(flags);
            let lookup = match this.lookup_path(dirfd, &path, at_flags, LookupIntent::Statx { context: cx.kernel }) {
                Ok(lookup) => lookup,
                Err(errno) => return Ok(DispatchOutcome::errno(errno)),
            };
            let _ = lookup.fast_path_answered();
            let _ = lookup.resolved_path();
            match lookup.into_stat() {
                Ok(record) => Ok(write_statx_record(memory, statxbuf, &record)),
                Err(errno) => Ok(DispatchOutcome::errno(errno)),
            }

        }

        fn fstat(this, cx, fd: Fd, statbuf: GuestPtr) {

            let fd: Fd = fd;
            let statbuf = statbuf.0;
            Ok(this.write_fd_stat(fd.0, statbuf, &mut *cx.memory))

        }

        fn name_to_handle_at(this, cx, dirfd: u64, pathname: GuestPtr, handle: GuestPtr, mount_id: GuestPtr, flags: u64) {
            const HANDLE_BYTES: u32 = 16;
            const MAX_HANDLE_BYTES: u32 = 128;
            const HANDLE_TYPE_CARRICK_FID: i32 = 1;
            const LEGACY_MOUNT_ID: i32 = 24;

            let allowed = LINUX_AT_SYMLINK_FOLLOW
                | LINUX_AT_EMPTY_PATH
                | carrick_abi::LINUX_AT_HANDLE_FID
                | carrick_abi::LINUX_AT_HANDLE_MNT_ID_UNIQUE
                | carrick_abi::LINUX_AT_HANDLE_CONNECTABLE;
            if flags & !allowed != 0
                || flags & carrick_abi::LINUX_AT_HANDLE_CONNECTABLE != 0
                    && flags
                        & (carrick_abi::LINUX_AT_HANDLE_FID | LINUX_AT_EMPTY_PATH)
                        != 0
            {
                return Ok(DispatchOutcome::errno(LINUX_EINVAL));
            }

            let path = read_guest_c_string(&*cx.memory, pathname.0)?;
            let record = if path.is_empty() {
                if flags & LINUX_AT_EMPTY_PATH == 0 {
                    return Ok(DispatchOutcome::errno(LINUX_ENOENT));
                }
                match this.fd_stat_record(dirfd as i32) {
                    Ok(record) => record,
                    Err(errno) => return Ok(DispatchOutcome::errno(errno)),
                }
            } else {
                let stat_flags = if flags & LINUX_AT_SYMLINK_FOLLOW != 0 {
                    0
                } else {
                    LINUX_AT_SYMLINK_NOFOLLOW
                };
                match this.path_stat_record(cx.kernel, dirfd, &path, stat_flags) {
                    Ok(record) => record,
                    Err(errno) => return Ok(DispatchOutcome::errno(errno)),
                }
            };

            // Identity-only handles can cover synthetic filesystems and never
            // promise that open_by_handle_at can decode them. Keep decodable
            // handles unsupported until that syscall has an authority model.
            if flags & carrick_abi::LINUX_AT_HANDLE_FID == 0 {
                return Ok(DispatchOutcome::errno(LINUX_EOPNOTSUPP));
            }

            let header = match cx.memory.read_bytes(handle.0, 8) {
                Ok(bytes) => bytes,
                Err(_) => return Ok(DispatchOutcome::errno(LINUX_EFAULT)),
            };
            let available = u32::from_le_bytes([header[0], header[1], header[2], header[3]]);
            if available > MAX_HANDLE_BYTES {
                return Ok(DispatchOutcome::errno(LINUX_EINVAL));
            }
            let mount_width = if flags & carrick_abi::LINUX_AT_HANDLE_MNT_ID_UNIQUE != 0 {
                8
            } else {
                4
            };
            if cx.memory.read_bytes(mount_id.0, mount_width).is_err() {
                return Ok(DispatchOutcome::errno(LINUX_EFAULT));
            }

            let mut encoded = [0u8; 24];
            encoded[..4].copy_from_slice(&HANDLE_BYTES.to_le_bytes());
            encoded[4..8].copy_from_slice(&HANDLE_TYPE_CARRICK_FID.to_le_bytes());
            let filesystem = match record.fs_identity {
                carrick_vfs::FsIdentity::Overlay => 1u64,
                carrick_vfs::FsIdentity::Pipe => 2,
                carrick_vfs::FsIdentity::Socket => 3,
                carrick_vfs::FsIdentity::Proc => 4,
                carrick_vfs::FsIdentity::Tmpfs => 5,
                carrick_vfs::FsIdentity::SecretMem => 6,
                carrick_vfs::FsIdentity::AnonInode => 7,
                carrick_vfs::FsIdentity::DevPts => 8,
                carrick_vfs::FsIdentity::Sysfs => 9,
            };
            encoded[8..16].copy_from_slice(&filesystem.to_le_bytes());
            encoded[16..24].copy_from_slice(&record.ino.to_le_bytes());

            let mount_write = if mount_width == 8 {
                cx.memory
                    .write_bytes(mount_id.0, &(LEGACY_MOUNT_ID as u64).to_le_bytes())
            } else {
                cx.memory
                    .write_bytes(mount_id.0, &LEGACY_MOUNT_ID.to_le_bytes())
            };
            if mount_write.is_err() {
                return Ok(DispatchOutcome::errno(LINUX_EFAULT));
            }
            let write_len = if available < HANDLE_BYTES { 8 } else { 24 };
            if cx.memory.write_bytes(handle.0, &encoded[..write_len]).is_err() {
                return Ok(DispatchOutcome::errno(LINUX_EFAULT));
            }
            if available < HANDLE_BYTES {
                return Ok(DispatchOutcome::errno(LINUX_EOVERFLOW));
            }
            Ok(DispatchOutcome::Returned { value: 0 })
        }

    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn name_to_handle_at_returns_identity_only_fid() {
        let mut dispatcher = SyscallDispatcher::new();
        let context = dispatcher.capture_one_task_context().unwrap();
        let reporter = CompatReporter::default();
        let base = 0x3000u64;
        let path_address = base;
        let handle_address = base + 0x100;
        let mount_address = base + 0x200;
        let mut memory = LinearMemory::new(base, vec![0u8; 0x1000]);
        memory
            .write_bytes(path_address, b"/proc/filesystems\0")
            .unwrap();
        memory
            .write_bytes(handle_address, &16u32.to_le_bytes())
            .unwrap();

        let out = dispatcher
            .dispatch(
                &context,
                SyscallRequest::new(
                    264,
                    SyscallArgs::from([
                        LINUX_AT_FDCWD,
                        path_address,
                        handle_address,
                        mount_address,
                        carrick_abi::LINUX_AT_HANDLE_FID,
                        0,
                    ]),
                ),
                &mut memory,
                &reporter,
            )
            .unwrap();
        assert_eq!(out, DispatchOutcome::Returned { value: 0 });
        let header = memory.read_bytes(handle_address, 8).unwrap();
        assert_eq!(u32::from_le_bytes(header[..4].try_into().unwrap()), 16);
        assert_eq!(i32::from_le_bytes(header[4..8].try_into().unwrap()), 1);
        assert_ne!(
            memory.read_bytes(handle_address + 8, 16).unwrap(),
            &[0u8; 16]
        );
    }

    #[test]
    fn name_to_handle_at_rejects_conflicting_handle_intent() {
        let mut dispatcher = SyscallDispatcher::new();
        let context = dispatcher.capture_one_task_context().unwrap();
        let reporter = CompatReporter::default();
        let mut memory = LinearMemory::new(0x3000, vec![0u8; 0x1000]);
        let out = dispatcher
            .dispatch(
                &context,
                SyscallRequest::new(
                    264,
                    SyscallArgs::from([
                        LINUX_AT_FDCWD,
                        0,
                        0,
                        0,
                        carrick_abi::LINUX_AT_HANDLE_FID | carrick_abi::LINUX_AT_HANDLE_CONNECTABLE,
                        0,
                    ]),
                ),
                &mut memory,
                &reporter,
            )
            .unwrap();
        assert_eq!(out, DispatchOutcome::errno(LINUX_EINVAL));
    }

    fn host_stream_file(
        host_fd: i32,
        pipe_id: u64,
        is_read_end: bool,
        write_kind: HostWriteKind,
    ) -> OpenFile {
        OpenFile::from_open_description_with_status_flags(
            Arc::new(RwLock::new(OpenDescription::HostPipe {
                base: OpenDescriptionBase::new(if is_read_end {
                    LINUX_O_RDONLY
                } else {
                    LINUX_O_WRONLY
                }),
                host_fd: HostFdRef::new(host_fd),
                is_read_end,
                pipe_id,
                pty: None,
                bidirectional: false,
                write_kind,
                stdio_stream: None,
            })),
            if is_read_end {
                LINUX_O_RDONLY
            } else {
                LINUX_O_WRONLY
            },
            0,
        )
    }

    #[test]
    fn host_stream_stats_distinguish_devices_and_preserve_pipe_identity() {
        let dispatcher = SyscallDispatcher::new();
        let mut pipe_fds = [-1; 2];
        // SAFETY: `pipe_fds` has space for both output descriptors.
        assert_eq!(unsafe { libc::pipe(pipe_fds.as_mut_ptr()) }, 0);
        // SAFETY: static NUL-terminated path; returned fd is owned below.
        let null_fd = unsafe { libc::open(c"/dev/null".as_ptr(), libc::O_WRONLY) };
        assert!(null_fd >= 0);

        let pipe_identity = host_inode_pipe_id(pipe_fds[0]);
        let null_identity = host_inode_pipe_id(null_fd);
        assert_ne!(pipe_identity, 0);
        assert_ne!(null_identity, 0);
        {
            let file_table = dispatcher.captured_file_table();
            let mut files = file_table.write_open_files();
            files.insert(
                20,
                host_stream_file(pipe_fds[0], pipe_identity, true, HostWriteKind::PipeLike),
            );
            files.insert(
                21,
                host_stream_file(pipe_fds[1], pipe_identity, false, HostWriteKind::PipeLike),
            );
            files.insert(
                22,
                host_stream_file(null_fd, null_identity, false, HostWriteKind::RegularFile),
            );
        }

        let pipe_read = dispatcher.fd_stat_record(20).expect("pipe read stat");
        let pipe_write = dispatcher.fd_stat_record(21).expect("pipe write stat");
        let null = dispatcher.fd_stat_record(22).expect("null stat");
        assert_eq!(pipe_read.ino, pipe_write.ino);
        assert_ne!(pipe_read.ino, null.ino);
        assert_eq!(pipe_read.mode & LINUX_S_IFMT, LINUX_S_IFIFO);
        assert_eq!(null.mode & LINUX_S_IFMT, LINUX_S_IFCHR);

        let pipe_link = dispatcher
            .open_file(20)
            .and_then(|file| file.description.read()?.readlink_target())
            .expect("pipe readlink target");
        assert_eq!(pipe_link, format!("pipe:[{}]", pipe_read.ino));
    }
}

crates/carrick-kernel/src/dispatch/fs/lo:
//! Unified path resolver for carrick filesystem dispatch.
//!
//! Unifies path resolution across `openat`, `stat`, `statx`, and the x86 stat variants,
//! ensuring consistent fast-path ordering, single dentry-cache lookups, stat-cache lookups,
//! synthetic /proc handling, rootfs containment, and trailing-slash directory forcing.

use parking_lot::RwLock;
use std::sync::Arc;

use super::*;
use carrick_vfs::rootfs::RootFsEntryKind;

/// Identifies which fast path (if any) fully resolved and answered the lookup.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(in crate::dispatch) enum FastPathKind {
    None,
    TrustedDirfd,
    DentryCache,
    StatCache,
    ImmutableLower,
}

/// The intent of the path lookup, distinguishing between open, stat, statx, etc.
pub(in crate::dispatch) enum LookupIntent<'a> {
    Stat {
        context: &'a crate::kernel::KernelContext,
    },
    Statx {
        context: &'a crate::kernel::KernelContext,
    },
    Open {
        context: &'a crate::kernel::KernelContext,
        registry: Option<&'a crate::thread::ThreadRegistry>,
        open_flags: LinuxOpenFlags,
        access: u64,
        writable_request: bool,
        flags: u64,
        reporter: &'a CompatReporter,
        reservation: &'a mut Option<crate::kernel::objects::FileSlotReservation>,
    },
}

/// The target or outcome produced by the path lookup.
pub(in crate::dispatch) enum LookupTarget {
    Resolved(String),
    Stat(StatRecord),
    OpenOutcome(DispatchOutcome),
}

/// Result of a unified path resolution.
pub(in crate::dispatch) struct PathLookup {
    pub resolved_path: String,
    pub fast_path: FastPathKind,
    pub target: LookupTarget,
}

impl PathLookup {
    /// Extracts the resolved [`StatRecord`], or returns `Err(ENOENT)` if the lookup
    /// was not for a stat intent or did not yield a stat record.
    pub(in crate::dispatch) fn into_stat(self) -> Result<StatRecord, LinuxErrno> {
        match self.target {
            LookupTarget::Stat(record) => Ok(record),
            _ => Err(LINUX_ENOENT),
        }
    }

    /// The resolved path string.
    pub(in crate::dispatch) fn resolved_path(&self) -> &str {
        &self.resolved_path
    }

    /// The fast path that answered this lookup (if any).
    pub(in crate::dispatch) fn fast_path(&self) -> FastPathKind {
        self.fast_path
    }

    /// Whether any fast path answered this lookup.
    pub(in crate::dispatch) fn fast_path_answered(&self) -> bool {
        self.fast_path != FastPathKind::None
    }
}

impl<'a> FsView<'a> {
    /// The single, unified path resolution entry point for filesystem operations.
    ///
    /// Handles:
    /// - Linux path length limit validation (`check_path_length`)
    /// - Empty path checks (e.g. `AT_EMPTY_PATH` for stat, `ENOENT` for open)
    /// - Pre-resolution fast paths (trusted dirfd, dentry cache, stat cache, immutable lower)
    /// - Rootfs containment and ancestor resolution (`resolve_at_path`)
    /// - Trailing slash and `.` / `..` directory forcing semantics
    /// - Post-resolution fast paths (ensuring dentry cache is consulted at most once)
    /// - Synthetic `/proc` and `/sys` virtual hierarchy lookups
    /// - Magic symlink resolution (`/proc/self/{exe,cwd,root}`)
    /// - Symlink following and loop / dangling link detection
    pub(in crate::dispatch) fn lookup_path(
        &self,
        dirfd: u64,
        path: &str,
        at_flags: carrick_abi::LinuxAtFlags,
        mut intent: LookupIntent<'_>,
    ) -> Result<PathLookup, LinuxErrno> {
        // 1. Empty pathname checks
        if path.is_empty() {
            match intent {
                LookupIntent::Stat { .. } | LookupIntent::Statx { .. } => {
                    // AT_EMPTY_PATH stats the dirfd/fd itself; without it an empty
                    // pathname is ENOENT — NOT a stat of the cwd (lstat02/stat02 case 2).
                    if at_flags.contains(carrick_abi::LinuxAtFlags::EMPTY_PATH) {
                        let record = self.fd_stat_record(dirfd as i32)?;
                        return Ok(PathLookup {
                            resolved_path: String::new(),
                            fast_path: FastPathKind::None,
                            target: LookupTarget::Stat(record),
                        });
                    }
                    return Err(LINUX_ENOENT);
                }
                LookupIntent::Open { .. } => {
                    // An empty pathname is never valid for open()/openat(): the kernel's
                    // path walk requires at least one component and returns ENOENT for ""
                    // (openat has no AT_EMPTY_PATH).
                    return Ok(PathLookup {
                        resolved_path: String::new(),
                        fast_path: FastPathKind::None,
                        target: LookupTarget::OpenOutcome(DispatchOutcome::errno(LINUX_ENOENT)),
                    });
                }
            }
        }

        // 2. Pre-resolution fast paths
        let mut dentry_attempted = false;
        let mut dentry_fast_open_attempted = false;

        match &mut intent {
            LookupIntent::Stat { .. } | LookupIntent::Statx { .. } => {
                // `--fs host` trusted-dirfd fast lane: `newfstatat(dirfd, name)` on
                // getdents output served straight off the trusted host dirfd.
                if let Some(result) = self.try_trusted_dirfd_stat(dirfd, path) {
                    let record = result?;
                    return Ok(PathLookup {
                        resolved_path: path.to_string(),
                        fast_path: FastPathKind::TrustedDirfd,
                        target: LookupTarget::Stat(record),
                    });
                }
            }
            LookupIntent::Open {
                open_flags,
                access,
                writable_request,
                flags,
                reservation,
                ..
            } => {
                let want_create = open_flags.contains(LinuxOpenFlags::CREAT);
                let want_trunc = open_flags.contains(LinuxOpenFlags::TRUNC);

                if !want_create
                    && !want_trunc
                    && (dirfd == LINUX_AT_FDCWD || (dirfd as i32) == -100 || path.starts_with('/'))
                    && path.starts_with('/')
                {
                    dentry_fast_open_attempted = true;
                    if let Some(outcome) = self.try_dentry_fast_open(
                        path,
                        *flags,
                        *access,
                        *writable_request,
                        reservation,
                    ) {
                        return Ok(PathLookup {
                            resolved_path: path.to_string(),
                            fast_path: FastPathKind::DentryCache,
                            target: LookupTarget::OpenOutcome(outcome),
                        });
                    }
                }

                if let Some(outcome) =
                    self.try_immutable_lower_absolute_open(dirfd, path, *flags, reservation)
                {
                    return Ok(PathLookup {
                        resolved_path: path.to_string(),
                        fast_path: FastPathKind::ImmutableLower,
                        target: LookupTarget::OpenOutcome(outcome),
                    });
                }

                if let Some(outcome) =
                    self.try_trusted_dirfd_openat(dirfd, path, *flags, reservation)
                {
                    return Ok(PathLookup {
                        resolved_path: path.to_string(),
                        fast_path: FastPathKind::TrustedDirfd,
                        target: LookupTarget::OpenOutcome(outcome),
                    });
                }
            }
        }

        // 3. Trailing slash and path length limits
        check_path_length(path)?;

        let requires_dir = path.ends_with('/') || path.ends_with("/.");

        let ends_with_dot = path == "."
            || path.ends_with("/.")
            || path.trim_end_matches('/').ends_with("/.")
            || path.trim_end_matches('/') == "."
            || path == ".."
            || path.ends_with("/..")
            || path.trim_end_matches('/').ends_with("/..")
            || path.trim_end_matches('/') == "..";
        let had_trailing_slash = path.len() > 1 && path.ends_with('/');

        let in_chroot = self
            .captured_fs_context()
            .chroot_root()
            .as_deref()
            .is_some_and(|r| r != "/");

        // 4. Pre-resolution dentry cache and stat cache (for stat / statx)
        if matches!(
            intent,
            LookupIntent::Stat { .. } | LookupIntent::Statx { .. }
        ) {
            if !in_chroot
                && (dirfd == LINUX_AT_FDCWD || (dirfd as i32) == -100 || path.starts_with('/'))
                && path.starts_with('/')
                && !path.starts_with("/proc")
                && !path.starts_with("/sys")
                && !path.starts_with("/dev")
                && !path.split('/').any(|c| c == "..")
                && self.dac_overrides_permissions()
                && !self.fs.vfs_mounts.has_mount(path)
            {
                dentry_attempted = true;
                let follow =
                    !at_flags.contains(carrick_abi::LinuxAtFlags::SYMLINK_NOFOLLOW) || requires_dir;
                match self.fs.rootfs_vfs.dentry_stat(path, follow) {
                    Ok(real) => {
                        if requires_dir && real.kind != RootFsEntryKind::Directory {
                            return Err(LINUX_ENOTDIR);
                        }
                        return Ok(PathLookup {
                            resolved_path: path.to_string(),
                            fast_path: FastPathKind::DentryCache,
                            target: LookupTarget::Stat(self.stat_record_with_device(path, &real)),
                        });
                    }
                    Err(LINUX_ENOENT) => return Err(LINUX_ENOENT),
                    Err(LINUX_ENOTDIR) => return Err(LINUX_ENOTDIR),
                    Err(LINUX_ELOOP) => return Err(LINUX_ELOOP),
                    Err(_) => {}
                }
            }

            if !in_chroot
                && !requires_dir
                && dirfd == LINUX_AT_FDCWD
                && path.starts_with('/')
                && !path.starts_with("/proc")
                && !path.starts_with("/sys")
                && !path.split('/').any(|c| c == "..")
                && self.dac_overrides_permissions()
                && let Some(real) = self.fs.rootfs_vfs.overlay.stat_cache_lookup(path)
            {
                return Ok(PathLookup {
                    resolved_path: path.to_string(),
                    fast_path: FastPathKind::StatCache,
                    target: LookupTarget::Stat(self.stat_record_with_device(path, &real)),
                });
            }
        }

        // 5. Rootfs boundary check and ancestor canonicalization
        let mut resolved = self.resolve_at_path(dirfd, path)?;

        // 6. Post-resolve directory validation for Open
        if let LookupIntent::Open { open_flags, .. } = &intent {
            let want_create = open_flags.contains(LinuxOpenFlags::CREAT);
            if ends_with_dot || had_trailing_slash {
                let followed = self
                    .canonicalize_following(&resolved)
                    .unwrap_or_else(|_| resolved.clone());
                match self.layered_metadata(&followed) {
                    Ok(md) => {
                        if md.kind == RootFsEntryKind::Directory {
                            if want_create {
                                return Ok(PathLookup {
                                    resolved_path: followed,
                                    fast_path: FastPathKind::None,
                                    target: LookupTarget::OpenOutcome(DispatchOutcome::errno(
                                        LINUX_EISDIR,
                                    )),
                                });
                            }
                            resolved = followed;
                        } else {
                            return Ok(PathLookup {
                                resolved_path: followed,
                                fast_path: FastPathKind::None,
                                target: LookupTarget::OpenOutcome(DispatchOutcome::errno(
                                    LINUX_ENOTDIR,
                                )),
                            });
                        }
                    }
                    Err(_) => {
                        if want_create && had_trailing_slash {
                            return Ok(PathLookup {
                                resolved_path: followed,
                                fast_path: FastPathKind::None,
                                target: LookupTarget::OpenOutcome(DispatchOutcome::errno(
                                    LINUX_EISDIR,
                                )),
                            });
                        }
                        return Ok(PathLookup {
                            resolved_path: followed,
                            fast_path: FastPathKind::None,
                            target: LookupTarget::OpenOutcome(DispatchOutcome::errno(LINUX_ENOENT)),
                        });
                    }
                }
            }
        }

        // 7. Post-resolve Dentry Cache (ONLY ONCE) and Stat Cache
        if matches!(
            intent,
            LookupIntent::Stat { .. } | LookupIntent::Statx { .. }
        ) {
            let follow =
                !at_flags.contains(carrick_abi::LinuxAtFlags::SYMLINK_NOFOLLOW) || requires_dir;
            if !dentry_attempted
                && !resolved.starts_with("/proc")
                && !resolved.starts_with("/sys")
                && !resolved.starts_with("/dev")
                && !resolved.split('/').any(|c| c == "..")
                && self.dac_overrides_permissions()
                && self.fs.vfs_mounts.resolve(&resolved).is_none()
            {
                match self.fs.rootfs_vfs.dentry_stat(&resolved, follow) {
                    Ok(real) => {
                        if requires_dir && real.kind != RootFsEntryKind::Directory {
                            return Err(LINUX_ENOTDIR);
                        }
                        return Ok(PathLookup {
                            resolved_path: resolved.clone(),
                            fast_path: FastPathKind::DentryCache,
                            target: LookupTarget::Stat(
                                self.stat_record_with_device(&resolved, &real),
                            ),
                        });
                    }
                    Err(LINUX_ENOENT) => return Err(LINUX_ENOENT),
                    Err(LINUX_ENOTDIR) => return Err(LINUX_ENOTDIR),
                    Err(LINUX_ELOOP) => return Err(LINUX_ELOOP),
                    Err(_) => {}
                }
            }

            if !requires_dir
                && !resolved.starts_with("/proc")
                && !resolved.starts_with("/sys")
                && !resolved.split('/').any(|c| c == "..")
                && self.dac_overrides_permissions()
                && let Some(real) = self.fs.rootfs_vfs.overlay.stat_cache_lookup(&resolved)
            {
                return Ok(PathLookup {
                    resolved_path: resolved.clone(),
                    fast_path: FastPathKind::StatCache,
                    target: LookupTarget::Stat(self.stat_record_with_device(&resolved, &real)),
                });
            }
        } else if let LookupIntent::Open {
            open_flags,
            access,
            writable_request,
            flags,
            reservation,
            ..
        } = &mut intent
        {
            let want_create = open_flags.contains(LinuxOpenFlags::CREAT);
            let want_trunc = open_flags.contains(LinuxOpenFlags::TRUNC);
            if !dentry_fast_open_attempted
                && !want_create
                && !want_trunc
                && !ends_with_dot
                && !had_trailing_slash
            {
                if let Some(outcome) = self.try_dentry_fast_open(
                    &resolved,
                    *flags,
                    *access,
                    *writable_request,
                    reservation,
                ) {
                    return Ok(PathLookup {
                        resolved_path: resolved,
                        fast_path: FastPathKind::DentryCache,
                        target: LookupTarget::OpenOutcome(outcome),
                    });
                }
            }
        }

        // 8. Synthetic /proc, /sys and leaf handling
        match intent {
            LookupIntent::Open {
                context,
                registry,
                open_flags,
                flags,
                reporter,
                reservation,
                ..
            } => {
                // Trace every open attempt
                crate::probes::path_open(&resolved, 0, 0);

                let visible_self = proc_visible_self(context);
                if let Some(n) = proc_self_fd_number(&resolved, visible_self) {
                    let outcome = self.reopen_proc_self_fd(
                        context,
                        registry,
                        n,
                        flags,
                        &resolved,
                        reporter,
                        reservation,
                    )?;
                    return Ok(PathLookup {
                        resolved_path: resolved,
                        fast_path: FastPathKind::None,
                        target: LookupTarget::OpenOutcome(outcome),
                    });
                }

                if let Some(n) = proc_self_fdinfo_number(&resolved, visible_self) {
                    let outcome = match self.fdinfo_bytes(n) {
                        Some(bytes) => {
                            self.install_proc_synthetic_bytes(&resolved, bytes, flags, reservation)
                        }
                        None => DispatchOutcome::errno(LINUX_ENOENT),
                    };
                    return Ok(PathLookup {
                        resolved_path: resolved,
                        fast_path: FastPathKind::None,
                        target: LookupTarget::OpenOutcome(outcome),
                    });
                }

                if proc_ns_link(&resolved).is_some()
                    || (resolved.starts_with("/proc/")
                        && resolved.contains("/ns/")
                        && crate::vfs::proc::proc_ns_link_type_with_context(
                            &resolved,
                            &self.synthetic_proc_context(context),
                        )
                        .is_some())
                {
                    return Ok(PathLookup {
                        resolved_path: resolved.clone(),
                        fast_path: FastPathKind::None,
                        target: LookupTarget::OpenOutcome(self.install_proc_synthetic_bytes(
                            &resolved,
                            Vec::new(),
                            flags,
                            reservation,
                        )),
                    });
                }

                if proc_self_magic_link(&resolved, visible_self) == Some("exe")
                    && !open_flags.contains(LinuxOpenFlags::NOFOLLOW)
                    && let Some(current) = self.cross.current_executable()
                {
                    let outcome =
                        self.install_proc_executable_source(&resolved, current, flags, reservation);
                    return Ok(PathLookup {
                        resolved_path: resolved,
                        fast_path: FastPathKind::None,
                        target: LookupTarget::OpenOutcome(outcome),
                    });
                }

                let mut path = match proc_self_magic_link(&resolved, visible_self) {
                    Some("exe") => {
                        let proc_ctx = self.synthetic_proc_context(context);
                        let exe = proc_ctx.executable_path;
                        if exe.starts_with("/proc/") {
                            resolved
                        } else {
                            exe
                        }
                    }
                    Some("cwd") => self.cwd(),
                    Some("root") => "/".to_string(),
                    _ => resolved,
                };

                let want_create = open_flags.contains(LinuxOpenFlags::CREAT);
                let want_excl = open_flags.contains(LinuxOpenFlags::EXCL);

                if !(open_flags.contains(LinuxOpenFlags::NOFOLLOW) || (want_create && want_excl)) {
                    let resolved_target = if want_create {
                        self.canonicalize_following_allow_missing(&path)
                    } else {
                        self.canonicalize_following(&path)
                    };
                    match resolved_target {
                        Ok(target) => path = target,
                        Err(e) if e == crate::linux_abi::LINUX_ELOOP => {
                            return Ok(PathLookup {
                                resolved_path: path,
                                fast_path: FastPathKind::None,
                                target: LookupTarget::OpenOutcome(DispatchOutcome::errno(e)),
                            });
                        }
                        Err(_) => {}
                    }
                } else if !(want_create && want_excl) {
                    if let Ok(md) = self.layered_lstat(&path)
                        && md.kind == RootFsEntryKind::Symlink
                    {
                        if open_flags.contains(LinuxOpenFlags::DIRECTORY) {
                            return Ok(PathLookup {
                                resolved_path: path,
                                fast_path: FastPathKind::None,
                                target: LookupTarget::OpenOutcome(DispatchOutcome::errno(
                                    LINUX_ENOTDIR,
                                )),
                            });
                        }
                        if open_flags.contains(LinuxOpenFlags::PATH) {
                            let status = flags & !LINUX_O_CLOEXEC;
                            let open_file = OpenFile::from_open_description_with_status_flags(
                                Arc::new(RwLock::new(OpenDescription::File {
                                    base: OpenDescriptionBase::new(status),
                                    path: path.clone(),
                                    metadata: md,
                                    contents: FileContents::dense(Vec::new()),
                                    offset: 0,
                                    writable: false,
                                })),
                                status,
                                linux_fd_flags_from_open_flags(flags),
                            );
                            let fd = match self.install_admitted_open_file(reservation, open_file) {
                                Ok(fd) => fd,
                                Err(errno) => {
                                    return Ok(PathLookup {
                                        resolved_path: path,
                                        fast_path: FastPathKind::None,
                                        target: LookupTarget::OpenOutcome(DispatchOutcome::errno(
                                            errno,
                                        )),
                                    });
                                }
                            };
                            self.record_fd_open_path(fd, path.clone());
                            return Ok(PathLookup {
                                resolved_path: path,
                                fast_path: FastPathKind::None,
                                target: LookupTarget::OpenOutcome(DispatchOutcome::returned_i32(
                                    fd,
                                )),
                            });
                        }
                        return Ok(PathLookup {
                            resolved_path: path,
                            fast_path: FastPathKind::None,
                            target: LookupTarget::OpenOutcome(DispatchOutcome::errno(
                                crate::linux_abi::LINUX_ELOOP,
                            )),
                        });
                    }
                }

                Ok(PathLookup {
                    resolved_path: path.clone(),
                    fast_path: FastPathKind::None,
                    target: LookupTarget::Resolved(path),
                })
            }
            LookupIntent::Stat { context } | LookupIntent::Statx { context } => {
                if crate::vfs::may_be_synthetic_virtual_path(&resolved) {
                    let proc_ctx = self.synthetic_proc_context(context);
                    if let Some(contents) = crate::vfs::proc::synthetic_file(&resolved, &proc_ctx) {
                        return Ok(PathLookup {
                            resolved_path: resolved.clone(),
                            fast_path: FastPathKind::None,
                            target: LookupTarget::Stat(StatRecord::synthetic(
                                &resolved,
                                contents.len(),
                                LINUX_S_IFREG | 0o444,
                            )),
                        });
                    }
                    if crate::vfs::proc::synthetic_dir_entries(&resolved, &proc_ctx).is_some() {
                        return Ok(PathLookup {
                            resolved_path: resolved.clone(),
                            fast_path: FastPathKind::None,
                            target: LookupTarget::Stat(StatRecord::synthetic(
                                &resolved,
                                0,
                                LINUX_S_IFDIR | 0o555,
                            )),
                        });
                    }
                    if let Some(size) =
                        crate::vfs::proc::proc_ns_link_size_with_context(&resolved, &proc_ctx)
                    {
                        return Ok(PathLookup {
                            resolved_path: resolved.clone(),
                            fast_path: FastPathKind::None,
                            target: LookupTarget::Stat(StatRecord::synthetic(
                                &resolved,
                                size as usize,
                                LINUX_S_IFLNK | 0o777,
                            )),
                        });
                    }
                }
                if let Some(contents) = crate::vfs::sys::synthetic_file(&resolved) {
                    return Ok(PathLookup {
                        resolved_path: resolved.clone(),
                        fast_path: FastPathKind::None,
                        target: LookupTarget::Stat(StatRecord::synthetic(
                            &resolved,
                            contents.len(),
                            LINUX_S_IFREG | 0o444,
                        )),
                    });
                }

                let follow =
                    !at_flags.contains(carrick_abi::LinuxAtFlags::SYMLINK_NOFOLLOW) || requires_dir;
                if let Some(real) = self.fs.rootfs_vfs.overlay.real_stat(&resolved, follow) {
                    if requires_dir && real.kind != RootFsEntryKind::Directory {
                        return Err(LINUX_ENOTDIR);
                    }
                    return Ok(PathLookup {
                        resolved_path: resolved.clone(),
                        fast_path: FastPathKind::None,
                        target: LookupTarget::Stat(self.stat_record_with_device(&resolved, &real)),
                    });
                }

                let path_is_symlink = follow
                    && self
                        .fs
                        .rootfs_vfs
                        .overlay
                        .real_stat(&resolved, false)
                        .is_some_and(|link| link.kind == RootFsEntryKind::Symlink);

                let path = if follow {
                    match self.canonicalize_following(&resolved) {
                        Ok(resolved_path) => resolved_path,
                        Err(errno) if errno == crate::linux_abi::LINUX_ELOOP => return Err(errno),
                        Err(_) => resolved,
                    }
                } else {
                    resolved
                };

                if let Some(real) = self.fs.rootfs_vfs.overlay.real_stat(&path, follow) {
                    if requires_dir && real.kind != RootFsEntryKind::Directory {
                        return Err(LINUX_ENOTDIR);
                    }
                    return Ok(PathLookup {
                        resolved_path: path.clone(),
                        fast_path: FastPathKind::None,
                        target: LookupTarget::Stat(self.stat_record_with_device(&path, &real)),
                    });
                }

                if path_is_symlink
                    && self
                        .layered_lstat(&path)
                        .is_ok_and(|md| md.kind == RootFsEntryKind::Symlink)
                {
                    return Err(LINUX_ENOENT);
                }

                use carrick_vfs::Vfs as _;
                if let Some(m) = self.fs.vfs_mounts.resolve(&path) {
                    if let Some(real) = m.vfs.real_stat(&m.full_path, follow) {
                        if requires_dir && real.kind != RootFsEntryKind::Directory {
                            return Err(LINUX_ENOTDIR);
                        }
                        return Ok(PathLookup {
                            resolved_path: path.clone(),
                            fast_path: FastPathKind::None,
                            target: LookupTarget::Stat(StatRecord::from_real(&real)),
                        });
                    }
                    if let Ok(md) = if follow {
                        m.vfs.lookup(&m.full_path)
                    } else {
                        m.vfs.lookup_nofollow(&m.full_path)
                    } {
                        if requires_dir && md.kind != carrick_vfs::EntryKind::Directory {
                            return Err(LINUX_ENOTDIR);
                        }
                        return Ok(PathLookup {
                            resolved_path: path.clone(),
                            fast_path: FastPathKind::None,
                            target: LookupTarget::Stat(StatRecord::from_metadata(
                                &vfs_md_to_rootfs_md_helper(&path, &md),
                            )),
                        });
                    }
                }

                let lookup = if follow {
                    self.fs.rootfs_vfs.lookup(&path)
                } else {
                    self.fs.rootfs_vfs.lookup_nofollow(&path)
                };
                lookup.and_then(|md| {
                    if requires_dir && md.kind != carrick_vfs::EntryKind::Directory {
                        return Err(LINUX_ENOTDIR);
                    }
                    Ok(PathLookup {
                        resolved_path: path.clone(),
                        fast_path: FastPathKind::None,
                        target: LookupTarget::Stat(self.layered_identity_record(
                            &path,
                            follow,
                            &vfs_md_to_rootfs_md_helper(&path, &md),
                        )),
                    })
                })
            }
        }
    }
}

crates/carrick-kernel/src/dispatch/forma:
//! Stat and statx record serialization and flag validation helpers.

use carrick_abi::{
    LINUX_AT_EACCESS, LINUX_AT_EMPTY_PATH, LINUX_AT_NO_AUTOMOUNT, LINUX_AT_SYMLINK_NOFOLLOW,
    LINUX_EFAULT, LINUX_PAGE_SIZE, LINUX_S_IFDIR, LINUX_S_IFLNK, LINUX_S_IFMT, LINUX_S_IFREG,
    LinuxStat, LinuxStatx, LinuxStatxTimestamp, LinuxX8664Stat,
};
pub(crate) use carrick_abi::{
    LINUX_AT_STATX_DONT_SYNC, LINUX_AT_STATX_FORCE_SYNC, LINUX_STATX_BASIC_STATS,
    LINUX_STATX_RESERVED,
};
use carrick_guest_mem::CurrentMmMemory;

use super::{
    DispatchOutcome, RootFsMetadata, StatRecord, blocks_512, linux_dev_major, linux_dev_minor,
    write_kernel_struct, write_kernel_struct_raw,
};

pub(crate) fn linux_statx_flags_are_supported(flags: u64) -> bool {
    const SUPPORTED: u64 = LINUX_AT_SYMLINK_NOFOLLOW
        | LINUX_AT_EMPTY_PATH
        | LINUX_AT_NO_AUTOMOUNT
        | LINUX_AT_STATX_FORCE_SYNC
        | LINUX_AT_STATX_DONT_SYNC;
    let sync = flags & (LINUX_AT_STATX_FORCE_SYNC | LINUX_AT_STATX_DONT_SYNC);
    flags & !SUPPORTED == 0 && sync != (LINUX_AT_STATX_FORCE_SYNC | LINUX_AT_STATX_DONT_SYNC)
}

pub(crate) fn linux_access_flags_are_supported(flags: u64) -> bool {
    const SUPPORTED: u64 = LINUX_AT_SYMLINK_NOFOLLOW | LINUX_AT_EACCESS | LINUX_AT_EMPTY_PATH;
    flags & !SUPPORTED == 0
}

pub(super) fn write_stat_record(
    memory: &mut impl CurrentMmMemory,
    statbuf: u64,
    record: &StatRecord,
) -> DispatchOutcome {
    let size = record.size_usize();
    let blocks = record
        .blocks
        .map(|b| b as i64)
        .unwrap_or_else(|| blocks_512(size));
    let stat = LinuxStat {
        st_dev: 1,
        st_ino: record.ino,
        st_mode: record.mode,
        st_nlink: record.nlink,
        st_uid: record.uid.raw(),
        st_gid: record.gid.raw(),
        st_rdev: record.rdev,
        __pad1: 0,
        st_size: record.size as i64,
        st_blksize: 4096,
        __pad2: 0,
        st_blocks: blocks,
        st_atime: record.atime.0,
        st_atime_nsec: record.atime.1 as u64,
        st_mtime: record.mtime.0,
        st_mtime_nsec: record.mtime.1 as u64,
        st_ctime: record.ctime.0,
        st_ctime_nsec: record.ctime.1 as u64,
        __unused4: 0,
        __unused5: 0,
    };

    if write_kernel_struct_raw(memory, statbuf, &stat).is_err() {
        DispatchOutcome::Errno {
            errno: LINUX_EFAULT,
        }
    } else {
        DispatchOutcome::Returned { value: 0 }
    }
}

pub(super) fn write_x8664_stat_record(
    memory: &mut impl CurrentMmMemory,
    statbuf: u64,
    record: &StatRecord,
) -> DispatchOutcome {
    let size = record.size_usize();
    let blocks = record
        .blocks
        .map(|b| b as i64)
        .unwrap_or_else(|| blocks_512(size));
    let stat = LinuxX8664Stat {
        st_dev: 1,
        st_ino: record.ino,
        st_nlink: record.nlink as u64,
        st_mode: record.mode,
        st_uid: record.uid.raw(),
        st_gid: record.gid.raw(),
        __pad0: 0,
        st_rdev: record.rdev,
        st_size: record.size as i64,
        st_blksize: 4096,
        st_blocks: blocks,
        st_atime: record.atime.0,
        st_atime_nsec: record.atime.1,
        st_mtime: record.mtime.0,
        st_mtime_nsec: record.mtime.1,
        st_ctime: record.ctime.0,
        st_ctime_nsec: record.ctime.1,
        __reserved: [0; 3],
    };

    if write_kernel_struct_raw(memory, statbuf, &stat).is_err() {
        DispatchOutcome::Errno {
            errno: LINUX_EFAULT,
        }
    } else {
        DispatchOutcome::Returned { value: 0 }
    }
}

/// Build a [`RealStat`](carrick_vfs::fs_backend::RealStat) from a live `libc::stat`
/// (e.g. an `fstat` of a host fd) carrying the REAL on-disk values: the true
/// file type (so a symlink stat'd with `AT_SYMLINK_NOFOLLOW` reports S_IFLNK)
/// and the real `st_nlink` (a true hard link reports more than 1). An fd-based
/// stat then reports the SAME real size/kind/times as the path-based
/// `real_stat` that statx/newfstatat use.
pub(super) fn real_stat_from_libc(st: &libc::stat) -> carrick_vfs::fs_backend::RealStat {
    use carrick_vfs::rootfs::RootFsEntryKind;
    let kind = match st.st_mode as u32 & LINUX_S_IFMT {
        m if m == LINUX_S_IFDIR => RootFsEntryKind::Directory,
        m if m == LINUX_S_IFLNK => RootFsEntryKind::Symlink,
        _ => RootFsEntryKind::File,
    };
    carrick_vfs::fs_backend::RealStat {
        kind,
        ino: st.st_ino,
        nlink: st.st_nlink as u32,
        mode: st.st_mode as u32 & 0o7777,
        uid: carrick_abi::NsUid::ROOT,
        gid: carrick_abi::NsGid::ROOT,
        size: st.st_size as u64,
        blocks: Some(st.st_blocks.max(0) as u64),
        atime: (st.st_atime, carrick_portable::stat_atime_nsec(st)),
        mtime: (st.st_mtime, carrick_portable::stat_mtime_nsec(st)),
        ctime: (st.st_ctime, carrick_portable::stat_ctime_nsec(st)),
    }
}

/// Build and write a `statx` record from a real backing stat.
pub(crate) fn write_statx_real(
    memory: &mut impl CurrentMmMemory,
    statxbuf: u64,
    real: &carrick_vfs::fs_backend::RealStat,
) -> DispatchOutcome {
    write_statx_record(memory, statxbuf, &StatRecord::from_real(real))
}

pub(crate) fn write_statx(
    memory: &mut impl CurrentMmMemory,
    statxbuf: u64,
    metadata: &RootFsMetadata,
) -> DispatchOutcome {
    write_statx_record(memory, statxbuf, &StatRecord::from_metadata(metadata))
}

pub(super) fn write_statx_record(
    memory: &mut impl CurrentMmMemory,
    statxbuf: u64,
    record: &StatRecord,
) -> DispatchOutcome {
    let zero_time = LinuxStatxTimestamp::zero();
    let stx_ts = |t: (i64, i64)| LinuxStatxTimestamp {
        tv_sec: t.0,
        tv_nsec: t.1 as u32,
        __reserved: 0,
    };
    let size = record.size_usize();
    let blocks = record.blocks.unwrap_or_else(|| blocks_512(size) as u64);
    let statx = LinuxStatx {
        stx_mask: LINUX_STATX_BASIC_STATS,
        stx_blksize: LINUX_PAGE_SIZE as u32,
        stx_attributes: 0,
        stx_nlink: record.nlink,
        stx_uid: record.uid.raw(),
        stx_gid: record.gid.raw(),
        stx_mode: record.mode as u16,
        __spare0: [0; 1],
        stx_ino: record.ino,
        stx_size: record.size,
        stx_blocks: blocks,
        stx_attributes_mask: 0,
        stx_atime: stx_ts(record.atime),
        stx_btime: zero_time,
        stx_ctime: stx_ts(record.ctime),
        stx_mtime: stx_ts(record.mtime),
        stx_rdev_major: linux_dev_major(record.rdev),
        stx_rdev_minor: linux_dev_minor(record.rdev),
        stx_dev_major: 0,
        stx_dev_minor: 1,
        stx_mnt_id: 1,
        stx_dio_mem_align: 0,
        stx_dio_offset_align: 0,
        stx_subvol: 0,
        stx_atomic_write_unit_min: 0,
        stx_atomic_write_unit_max: 0,
        stx_atomic_write_segments_max: 0,
        stx_dio_read_offset_align: 0,
        stx_atomic_write_unit_max_opt: 0,
        __spare2: [0; 1],
        __spare3: [0; 8],
    };
    write_kernel_struct(memory, statxbuf, &statx)
}

pub(crate) fn write_synthetic_statx(
    memory: &mut impl CurrentMmMemory,
    statxbuf: u64,
    path: &str,
    size: usize,
) -> DispatchOutcome {
    write_synthetic_statx_mode(memory, statxbuf, path, size, LINUX_S_IFREG | 0o444)
}

pub(crate) fn write_synthetic_statx_mode(
    memory: &mut impl CurrentMmMemory,
    statxbuf: u64,
    path: &str,
    size: usize,
    mode: u32,
) -> DispatchOutcome {
    write_statx_record(memory, statxbuf, &StatRecord::synthetic(path, size, mode))
}

